method SquareArray(arr: array<int>) returns (result: array<int>)
  requires arr != null
  ensures result != null
  ensures result.Length == arr.Length
  ensures forall i :: 0 <= i < arr.Length ==> result[i] == arr[i] * arr[i]
{
  // Handle empty array case
  result := new int[arr.Length];
  var index := 0;

  while index < arr.Length
    invariant 0 <= index <= arr.Length
    invariant forall i :: 0 <= i < index ==> result[i] == arr[i] * arr[i]
    decreases arr.Length - index
  {
    // Square the current element (handles negative numbers correctly)
    result[index] := arr[index] * arr[index];

    // Assert intermediate invariant
    assert forall i :: 0 <= i <= index ==> result[i] == arr[i] * arr[i];

    index := index + 1;
  }

  // Final verification of the postcondition
  assert forall i :: 0 <= i < arr.Length ==> result[i] == arr[i] * arr[i];
}

// Auxiliary lemma to help verify the square property
lemma SquarePropertyLemma(arr: array<int>, result: array<int>, start: int, end: int)
  requires arr != null && result != null
  requires 0 <= start <= end <= arr.Length
  requires arr.Length == result.Length
  requires forall i :: start <= i < end ==> result[i] == arr[i] * arr[i]
  ensures forall i :: start <= i < end ==> result[i] == arr[i] * arr[i]
{
  // This lemma is trivial but helps structure the verification
}

